package br.com.mecaniQA.api.service;
import br.com.mecaniQA.api.Repository.*;import br.com.mecaniQA.api.model.*;import br.com.mecaniQA.api.Enums.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class OrdemServicoService { private final OrdemServicoRepository repo=OrdemServicoRepository.getInstance();private final ClienteRepository clientes=ClienteRepository.getInstance();private final VeiculoRepository veiculos=VeiculoRepository.getInstance(); public Cliente buscarCliente(Long id){return clientes.buscarPorId(id);}public Veiculo buscarVeiculo(Long id){return veiculos.buscarPorId(id);}public OrdemServico cadastrar(OrdemServico x){return repo.cadastrar(x);}public OrdemServico buscarPorNumero(Long id){return repo.buscarPorNumero(id);}public List<OrdemServico>listarTodas(){return repo.listarTodas();}public List<OrdemServico>buscarPorStatus(StatusOrdemServico s){return repo.buscarPorStatus(s);}public OrdemServico atualizarStatus(Long id,StatusOrdemServico s){return repo.atualizarStatus(id,s);}public OrdemServico deletar(Long id){return repo.deletar(id);}}
